60: /* Called with the sev_bitmap_lock held, or on shutdown  */
61: static int sev_flush_asids(int min_asid, int max_asid)
62: {
63: 	int ret, pos, error = 0;
64: 
65: 	/* Check if there are any ASIDs to reclaim before performing a flush */
66: 	pos = find_next_bit(sev_reclaim_asid_bitmap, max_asid, min_asid);
67: 	if (pos >= max_asid)
68: 		return -EBUSY;
69: 
70: 	/*
71: 	 * DEACTIVATE will clear the WBINVD indicator causing DF_FLUSH to fail,
72: 	 * so it must be guarded.
73: 	 */
74: 	down_write(&sev_deactivate_lock);
75: 
76: 	wbinvd_on_all_cpus();
77: 	ret = sev_guest_df_flush(&error);
78: 
79: 	up_write(&sev_deactivate_lock);
80: 
81: 	if (ret)
82: 		pr_err("SEV: DF_FLUSH failed, ret=%d, error=%#x\n", ret, error);
83: 
84: 	return ret;
85: }
86: 
87: /* Must be called with the sev_bitmap_lock held */
88: static bool __sev_recycle_asids(int min_asid, int max_asid)
89: {
90: 	if (sev_flush_asids(min_asid, max_asid))
91: 		return false;
92: 
93: 	/* The flush process will flush all reclaimable SEV and SEV-ES ASIDs */
94: 	bitmap_xor(sev_asid_bitmap, sev_asid_bitmap, sev_reclaim_asid_bitmap,
95: 		   max_sev_asid);
96: 	bitmap_zero(sev_reclaim_asid_bitmap, max_sev_asid);
97: 
98: 	return true;
